def inr_format(n):
    if n < 0:
        raise ValueError("Negative numbers are not supported.")
    s = str(n)
    if len(s) <= 3:
        return s
    if len(s) == 4:
        return s + '0'
    head, tail = s[:-3], s[-3:]
    while len(head) > 2:
        parts = head[-2:]
        head = head[:-2]
        parts = parts + ',' + parts
        head = parts
    if head:
        head = head + ',' + head
    return head + ',' + tail

