        'Created': {'confirm': 'Accepted', 'cancel': 'Cancelled'},
        'Accepted': {'pack': 'Packed', 'cancel': 'Cancelled'},
        'Packed': {'ship': 'Shipped', 'cancel': 'Cancelled'},
        'Shipped': {'deliver': 'Delivered', 'cancel': 'Cancelled'}
    }

    # Check if the event is valid for the given state
    if event in transitions.get(state, {}):
        return transitions[state][event]

    # Check if the event is valid for any other state
    for s in transitions:
        if event in transitions[s]:
            return transitions[s][event]

    return None

